#!/usr/bin/env python3
"""Publish an Uncovr baseline as an Open Knowledge Format (OKF v0.2) bundle for an LLM wiki.

Usage: python3 okf.py [repository root] --target obsidian|mkdocs|knowledge-catalog [--source-url TEMPLATE]

Standard library only and self-contained. Reads product-context/ and .uncovr/state.json;
writes only product-context/wiki/ (rebuilt on every run, its log.md kept) and, for MkDocs,
product-context/mkdocs.yml. Git is used read-only to link sources. It never publishes to a
service: pushing the bundle anywhere is left to the person.
"""
from __future__ import annotations

import argparse
from collections import Counter
from datetime import datetime, timezone
import json
import os
from pathlib import Path
import re
import shutil
import subprocess
import sys

GENERATOR = "uncovr/0.4.0"
OKF_VERSION = "0.2"
TARGETS = ("obsidian", "mkdocs", "knowledge-catalog")
MARKER = "<!-- Generated by Uncovr from product-context/. Edit the sources there, not this folder. -->"
MKDOCS_MARKER = "# Generated by Uncovr"
DOCUMENTS = {
    "overview.md": ("Product Overview", "What the product is and the revision the baseline was reconstructed at."),
    "features.md": ("Feature Catalog", "Features, acceptance criteria, parameters and background work observed in the code."),
    "domain.md": ("Domain Model", "Glossary, entities, business rules, states, permissions and sensitive data."),
    "architecture.md": ("Architecture", "Components, contracts, deployment, constraints, debt and regression hotspots."),
    "traceability.md": ("Traceability", "From rules to code and tests, and from code to the features it affects."),
    "validation.md": ("Validation Sheet", "Confidence, open questions for the Product Owner and review outcomes."),
}
KINDS = {
    "feature": ("Feature", "features"),
    "business_rule": ("Business Rule", "rules"),
    "architecture": ("Architecture Fact", "architecture"),
    "constraint": ("Constraint", "constraints"),
    "decision": ("Decision", "decisions"),
    "assumption": ("Assumption", "assumptions"),
}
CLAIM_ID = re.compile(r"(?<![\[\w/-])([A-Z][A-Z0-9]*-[0-9]{3,})(?![\w-]|\]\()")
LOCAL = {"code", "test", "config"}


def git(root: Path, *args: str) -> str | None:
    try:
        result = subprocess.run(["git", "-C", str(root), *args], capture_output=True, text=True, check=False)
    except OSError:
        return None
    return result.stdout.strip() if result.returncode == 0 else None


def github_template(root: Path) -> str | None:
    """A source URL template for GitHub remotes; other hosts need --source-url."""
    remote = git(root, "remote", "get-url", "origin") or ""
    match = re.match(r"^(?:git@github\.com:|https://github\.com/)([^/]+/[^/]+?)(?:\.git)?/?$", remote)
    return f"https://github.com/{match.group(1)}/blob/{{revision}}/{{path}}#L{{start}}-L{{end}}" if match else None


def y(value) -> str:
    """A YAML scalar or flow collection; JSON strings are valid YAML."""
    if isinstance(value, dict):
        return "{ " + ", ".join(f"{k}: {y(v)}" for k, v in value.items()) + " }"
    if isinstance(value, list):
        return "[" + ", ".join(y(v) for v in value) + "]"
    return json.dumps(value, ensure_ascii=False)


def frontmatter(fields: dict) -> str:
    lines = ["---"]
    for key, value in fields.items():
        if key == "sources":
            lines.append("sources:")
            lines += [f"  - {y(source)}" for source in value]
        else:
            lines.append(f"{key}: {y(value)}")
    return "\n".join(lines + ["---", ""])


def iso(value: str) -> str:
    return f"{value}T00:00:00Z" if re.fullmatch(r"\d{4}-\d{2}-\d{2}", value) else value


def slug(text: str) -> str:
    return re.sub(r"[^a-z0-9]+", "-", text.lower()).strip("-")


def href(source: str, target: str, mode: str) -> str:
    if mode == "knowledge-catalog":
        return "/" + target
    return Path(os.path.relpath(target, start=os.path.dirname(source) or ".")).as_posix()


def link_claims(text: str, source: str, pages: dict[str, str], mode: str) -> str:
    def replace(match: re.Match) -> str:
        claim = match.group(1)
        return f"[{claim}]({href(source, pages[claim], mode)})" if claim in pages else claim
    return CLAIM_ID.sub(replace, text)


def strip_frontmatter(text: str) -> str:
    if text.startswith("---\n"):
        end = text.find("\n---", 4)
        if end != -1:
            return text[end + 4:].lstrip("\n")
    return text


def load_claims(context: Path) -> list[dict]:
    path = context / "evidence.jsonl"
    claims = []
    if path.is_file():
        for line in path.read_text(encoding="utf-8").splitlines():
            try:
                record = json.loads(line) if line.strip() else None
            except ValueError:
                continue
            if isinstance(record, dict) and isinstance(record.get("id"), str) and record.get("kind") in KINDS:
                claims.append(record)
    return claims


def source_entries(claim: dict, template: str | None, revision: str | None) -> list[dict]:
    entries = []
    for index, item in enumerate(claim.get("evidence") or [], 1):
        if not isinstance(item, dict) or not item.get("ref"):
            continue
        ref, start, end = str(item["ref"]), item.get("line_start"), item.get("line_end")
        rev = item.get("revision") or revision
        lines = f", lines {start}\u2013{end}" if start else ""
        if item.get("type") in LOCAL and template and rev:
            resource = template.format(revision=rev, path=ref, start=start or 1, end=end or start or 1)
            if not start:
                resource = resource.split("#", 1)[0]
        elif item.get("type") in LOCAL:
            resource = ref + (f"#L{start}-L{end}" if start else "") + (f"@{rev[:12]}" if rev else "")
        else:
            resource = ref
        entries.append({"id": f"s{index}", "resource": resource, "title": f"{item.get('type', 'source')}: {ref}{lines}"})
    return entries


def status_of(claim: dict) -> str:
    business = claim.get("business_validation")
    if business == "approved" or (business == "not_applicable" and claim.get("confidence") == "confirmed"):
        return "stable"
    return "deprecated" if business == "rejected" else "draft"


def claim_page(claim: dict, path: str, sources: list[dict], mentions: list[str], at: str,
               revision: str | None, mode: str) -> str:
    kind, _ = KINDS[claim["kind"]]
    fields = {
        "type": kind,
        "title": claim["id"],
        "description": claim.get("summary", ""),
        "tags": ["uncovr", slug(claim["kind"]), claim.get("confidence", "unknown")],
        "status": status_of(claim),
        "generated": {"by": GENERATOR, "at": at},
    }
    if claim.get("business_validation") == "approved" and claim.get("validated_by"):
        fields["verified"] = {"by": "human:" + slug(str(claim["validated_by"])), "at": iso(str(claim.get("validated_on", "")))}
    if sources:
        fields["sources"] = sources
    fields.update({"uncovr_id": claim["id"], "confidence": claim.get("confidence"),
                   "business_validation": claim.get("business_validation")})
    if revision:
        fields["revision"] = revision
    if mode == "obsidian":
        fields["aliases"] = [claim["id"]]
    notes = "".join(f"[^{s['id']}]" for s in sources)
    body = [f"# {claim['id']}", "", f"{claim.get('summary', '')}{notes}", "",
            "| Confidence | Business validation |", "| --- | --- |",
            f"| {claim.get('confidence')} | {claim.get('business_validation')} |", ""]
    if claim.get("business_validation") == "rejected":
        body += ["The code does this, but the business rejected it as the intended rule.", ""]
    if mentions:
        body += ["Mentioned in: " + ", ".join(
            f"[{DOCUMENTS[m][0]}]({href(path, m, mode)})" for m in mentions), ""]
    body += [f"[^{s['id']}]: {s['title']}" for s in sources]
    return frontmatter(fields) + "\n".join(body).rstrip() + "\n"


def updated_log(previous: str | None, day: str, entry: str) -> str:
    sections = re.split(r"(?m)^(?=## )", previous or "")[1:]
    kept = [s.rstrip() for s in sections if not s.startswith(f"## {day}")]
    return "\n\n".join(["# Update Log", f"## {day}\n* **Update**: {entry}", *kept]) + "\n"


def conformance(bundle: Path) -> list[str]:
    """OKF v0.2 section 11: every non-reserved .md has frontmatter with a non-empty type."""
    problems = []
    for path in sorted(bundle.rglob("*.md")):
        if path.name in {"index.md", "log.md"}:
            continue
        text = path.read_text(encoding="utf-8")
        head = text.split("\n---", 1)[0] if text.startswith("---\n") else ""
        if not re.search(r'(?m)^type: "?[^"\s]', head):
            problems.append(f"{path.relative_to(bundle).as_posix()}: missing type")
    return problems


def export(root: Path, mode: str, source_url: str | None = None, at: str | None = None) -> tuple[Path, list[str]]:
    root = root.expanduser().resolve()
    context = root / "product-context"
    bundle = context / "wiki"
    if context.is_symlink():
        raise RuntimeError("product-context/ must not be a symlink")
    if not context.is_dir():
        raise RuntimeError("product-context/ not found; run the Uncovr workflow first")
    if mode == "mkdocs" and (context / "mkdocs.yml").is_symlink():
        raise RuntimeError("product-context/mkdocs.yml must not be a symlink")
    if bundle.is_symlink() or (bundle.exists() and MARKER not in _read(bundle / "index.md")):
        raise RuntimeError("product-context/wiki exists and was not generated by Uncovr; move it away first")
    at = at or datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    state = json.loads(_read(root / ".uncovr" / "state.json") or "{}")
    revision = state.get("baseline_revision") or git(root, "rev-parse", "HEAD")
    template = source_url or github_template(root)
    claims = load_claims(context)
    pages = {c["id"]: f"{KINDS[c['kind']][1]}/{slug(c['id'])}.md" for c in claims}
    texts = {name: strip_frontmatter(_read(context / name)) for name in DOCUMENTS if (context / name).is_file()}
    notes: list[str] = []
    log = _read(bundle / "log.md") or None
    if bundle.exists():
        shutil.rmtree(bundle)
    bundle.mkdir(parents=True)
    doc_status = "stable" if state.get("phase") == "baseline_reviewed" else "draft"
    for name, text in texts.items():
        kind, description = DOCUMENTS[name]
        fields = {"type": kind, "title": kind, "description": description, "tags": ["uncovr"],
                  "status": doc_status, "generated": {"by": GENERATOR, "at": at}}
        if revision:
            fields["revision"] = revision
        _write(bundle / name, frontmatter(fields) + link_claims(text, name, pages, mode))
    missing_urls = 0
    for claim in claims:
        sources = source_entries(claim, template, revision)
        missing_urls += sum(1 for s in sources
                            if s["title"].split(":")[0] in LOCAL and not s["resource"].startswith("http"))
        mentions = [n for n, t in texts.items() if re.search(rf"\b{re.escape(claim['id'])}\b", t)]
        _write(bundle / pages[claim["id"]],
               claim_page(claim, pages[claim["id"]], sources, mentions, at, revision, mode))
    groups: dict[str, list[dict]] = {}
    for claim in claims:
        groups.setdefault(KINDS[claim["kind"]][1], []).append(claim)
    for folder, members in groups.items():
        title = next(k for k, f in KINDS.values() if f == folder)
        lines = [f"# {title}s", ""] + [
            f"* [{c['id']}]({href(f'{folder}/index.md', pages[c['id']], mode)}) - {c.get('summary', '')}"
            for c in sorted(members, key=lambda c: c["id"])]
        _write(bundle / folder / "index.md", "\n".join(lines) + "\n")
    index = ["---", f'okf_version: "{OKF_VERSION}"', "---", MARKER, "", "# Product context", ""]
    index += [f"* [{DOCUMENTS[n][0]}]({href('index.md', n, mode)}) - {DOCUMENTS[n][1]}" for n in texts]
    index += ["", "# Claims", ""] + [
        f"* [{next(k for k, f in KINDS.values() if f == folder)}s]({href('index.md', f'{folder}/index.md', mode)})"
        f" - {len(members)} claim(s)" for folder, members in sorted(groups.items())]
    _write(bundle / "index.md", "\n".join(index) + "\n")
    counts = Counter(c.get("confidence") for c in claims)
    approved = sum(1 for c in claims if c.get("business_validation") == "approved")
    summary = ", ".join(f"{n} {k}" for k, n in sorted(counts.items()))
    _write(bundle / "log.md", updated_log(log, at[:10], f"Exported {len(claims)} claim(s) ({summary or 'none'};"
                                                       f" {approved} approved) at revision {(revision or 'unknown')[:12]}."))
    if mode == "mkdocs":
        config = context / "mkdocs.yml"
        if config.exists() and MKDOCS_MARKER not in _read(config):
            notes.append("product-context/mkdocs.yml exists and is not Uncovr's; left unchanged.")
        else:
            name = root.name or "product"
            _write(config, f"{MKDOCS_MARKER}; edit product-context/, then re-run okf.py.\n"
                           f"site_name: {y(name + ' product context')}\ndocs_dir: wiki\n"
                           "markdown_extensions:\n  - tables\n  - footnotes\n")
    if missing_urls:
        notes.append(f"{missing_urls} source(s) have no URL (no GitHub remote); pass --source-url to link them.")
    return bundle, notes + conformance(bundle)


def _read(path: Path) -> str:
    return path.read_text(encoding="utf-8") if path.is_file() else ""


def _write(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8")


NEXT_STEPS = {
    "obsidian": "Open product-context/wiki as a vault in Obsidian, or copy it into your vault. "
                "Claim IDs are aliases, so [[BR-001]]-style links resolve; the graph view shows the links.",
    "mkdocs": "Install MkDocs (pip install mkdocs), then run: mkdocs serve -f product-context/mkdocs.yml",
    "knowledge-catalog": "Publish product-context/wiki with Knowledge Catalog's OKF push (kcmd) in a Google Cloud "
                         "project you may write to. Uncovr does not publish; only .md files are ingested.",
}


def main() -> int:
    parser = argparse.ArgumentParser(description="Publish an Uncovr baseline as an OKF bundle")
    parser.add_argument("target_dir", nargs="?", default=".")
    parser.add_argument("--target", choices=TARGETS, required=True)
    parser.add_argument("--source-url", help="e.g. https://host/repo/blob/{revision}/{path}#L{start}-L{end}")
    args = parser.parse_args()
    try:
        bundle, notes = export(Path(args.target_dir), args.target, args.source_url)
    except (OSError, RuntimeError, ValueError) as error:
        print(f"ERROR: {error}", file=sys.stderr)
        return 1
    print(f"OKF {OKF_VERSION} bundle for {args.target}: {bundle}")
    for note in notes:
        print(f"NOTE: {note}")
    print(NEXT_STEPS[args.target])
    return 0


if __name__ == "__main__":
    sys.exit(main())
